void FieldToSqlite(VulkanSqlitePreparedStatements& statements, const FieldInfo &fieldInfo, size_t fieldIndex, std::string_view fieldName, const StdVideoAV1ChromaSamplePosition& value, std::string_view typeName)
{
    switch (value) {
        case STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_UNKNOWN:
            RecordField<std::string_view>(statements, fieldInfo, fieldIndex, fieldName, "StdVideoAV1ChromaSamplePosition", "STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_UNKNOWN");
            break;
        case STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_VERTICAL:
            RecordField<std::string_view>(statements, fieldInfo, fieldIndex, fieldName, "StdVideoAV1ChromaSamplePosition", "STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_VERTICAL");
            break;
        case STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_COLOCATED:
            RecordField<std::string_view>(statements, fieldInfo, fieldIndex, fieldName, "StdVideoAV1ChromaSamplePosition", "STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_COLOCATED");
            break;
        case STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_RESERVED:
            RecordField<std::string_view>(statements, fieldInfo, fieldIndex, fieldName, "StdVideoAV1ChromaSamplePosition", "STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_RESERVED");
            break;
        case STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_INVALID:
            RecordField<std::string_view>(statements, fieldInfo, fieldIndex, fieldName, "StdVideoAV1ChromaSamplePosition", "STD_VIDEO_AV1_CHROMA_SAMPLE_POSITION_INVALID");
            break;
        default:
            RecordFieldAsHexFixedWidth<StdVideoAV1ChromaSamplePosition>(statements, fieldInfo, fieldIndex, fieldName, "StdVideoAV1ChromaSamplePosition", value);
            break;
    }
}

